// Version 2 keeps each audio source once in `media` (keyed by asset id, shared by
// copies of a project). `contents` only holds the editable state and references,
// so saving rewrites the montage, never the recordings already stored.
let opening;
const VERSION=2;
export function openDatabase(){return opening??=new Promise((resolve,reject)=>{if(!globalThis.indexedDB){reject(Error('Le stockage du navigateur est indisponible.'));return;}const request=indexedDB.open('onde-projects',VERSION);request.onupgradeneeded=e=>{const db=request.result;if(e.oldVersion<1){db.createObjectStore('projects',{keyPath:'id'});db.createObjectStore('contents',{keyPath:'id'});}if(e.oldVersion<2){db.createObjectStore('media',{keyPath:'id'});migrateContents(request.transaction);}};request.onsuccess=()=>{const db=request.result;db.onversionchange=()=>{db.close();opening=null;};resolve(db);};request.onerror=()=>{opening=null;reject(request.error);};request.onblocked=()=>{reject(Error('Fermez les autres onglets Onde puis réessayez.'));opening=null;};});}
// Version 1 stored every blob inside its project record: move them out once.
function migrateContents(tx){const contents=tx.objectStore('contents'),media=tx.objectStore('media');contents.openCursor().onsuccess=e=>{const cursor=e.target.result;if(!cursor)return;const record=cursor.value;if(Array.isArray(record.assets)&&record.assets.some(a=>a.blob instanceof Blob)){for(const a of record.assets)if(a.blob instanceof Blob)media.put({id:a.id,blob:a.blob});cursor.update({...record,assets:record.assets.map(assetRef)});}cursor.continue();};}
const assetRef=({blob,wave,...a})=>({...a,type:blob?.type||a.type||'',size:blob?.size??a.size??0});
export async function listProjects(){const db=await openDatabase();return new Promise((resolve,reject)=>{const req=db.transaction('projects').objectStore('projects').getAll();req.onsuccess=()=>resolve(req.result.sort((a,b)=>b.savedAt-a.savedAt));req.onerror=()=>reject(req.error);});}
// Blobs read from IndexedDB are lazy handles: joining them costs no audio read.
export async function readProject(id){const db=await openDatabase();return new Promise((resolve,reject)=>{const tx=db.transaction(['contents','media']),req=tx.objectStore('contents').get(id);let result,error;req.onsuccess=()=>{const record=req.result;if(!record)return;const assets=record.assets.map(a=>({...a}));result={...record,assets};const media=tx.objectStore('media');for(const a of assets){if(a.blob instanceof Blob)continue;const m=media.get(a.id);m.onsuccess=()=>{if(!m.result)error??=Error('Source audio manquante dans le navigateur : '+(a.name||a.id));else{a.blob=m.result.blob;a.wave=m.result.wave||null;}};}};tx.oncomplete=()=>error?reject(error):resolve(result);tx.onerror=()=>reject(tx.error);});}
// Sources no longer referenced by any project are removed with the last one.
function collectOrphans(tx,candidates){if(!candidates.size)return;const req=tx.objectStore('contents').getAll();req.onsuccess=()=>{for(const r of req.result)for(const a of r.assets||[])candidates.delete(a.id);const media=tx.objectStore('media');for(const id of candidates)media.delete(id);};}
export async function writeProject(record,expectedRevision=0){const db=await openDatabase();return new Promise((resolve,reject)=>{const tx=db.transaction(['projects','contents','media'],'readwrite');let error,revision;const store=tx.objectStore('projects'),req=store.get(record.id);req.onsuccess=()=>{const old=req.result;if((old?.revision||0)!==expectedRevision){error=Error('Ce projet a changé dans un autre onglet. Utilisez « Sauvegarder sous » pour conserver votre montage.');tx.abort();return;}revision=expectedRevision+1;const savedAt=Date.now(),media=tx.objectStore('media'),contents=tx.objectStore('contents'),ids=new Set(record.assets.map(a=>a.id));
for(const a of record.assets){const existing=media.get(a.id);existing.onsuccess=()=>{const m=existing.result;if(!m||m.blob.size!==a.blob.size)media.put({id:a.id,blob:a.blob,wave:a.wave||null});else if(a.wave&&(m.wave?.length!==a.wave.length||m.wave?.rate!==a.wave.rate))media.put({...m,wave:a.wave});};}
store.put({id:record.id,name:record.state.name,revision,savedAt,bytes:record.assets.reduce((n,a)=>n+a.blob.size,0),tracks:record.state.tracks.length,duration:Math.max(0,...record.state.clips.map(c=>c.start+c.duration))});
const previous=contents.get(record.id);previous.onsuccess=()=>{const dropped=new Set((previous.result?.assets||[]).map(a=>a.id).filter(id=>!ids.has(id)));contents.put({...record,assets:record.assets.map(assetRef),revision,savedAt});collectOrphans(tx,dropped);};};tx.oncomplete=()=>resolve(revision);tx.onerror=()=>reject(error||tx.error||Error('Enregistrement impossible.'));tx.onabort=()=>reject(error||tx.error||Error('Enregistrement annulé.'));});}
export async function deleteProject(id){const db=await openDatabase();return new Promise((resolve,reject)=>{const tx=db.transaction(['projects','contents','media'],'readwrite'),contents=tx.objectStore('contents'),req=contents.get(id);req.onsuccess=()=>{const ids=new Set((req.result?.assets||[]).map(a=>a.id));tx.objectStore('projects').delete(id);contents.delete(id).onsuccess=()=>collectOrphans(tx,ids);};tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error);});}
